struct UnionFind
  getter parents
  @parents: Array(Int32)
  @ranks:   Array(Int32)

  def initialize(size)
    @ranks   = Array(Int32).new(size, 0)
    @parents = Array(Int32).new(size, &.to_i32)
  end

  def unite(a, b)
    a = root(a)
    b = root(b)
    return if a == b
    @ranks[b] += 1 if @ranks[a] == @ranks[b]
    @parents[b] = a
  end

  def root(a)
    while a != @parents[a]
      a = @parents[a] = @parents[@parents[a]]
    end
    a
  end

  def same?(a, b)
    root(a) == root(b)
  end

  def size(a)
    -@parents[a]
  end
end

