constexpr std::int32_t INF = 1001001001;
constexpr std::int64_t LINF = 1001001001001001001;

class UnionFind {
public:
    UnionFind(const int n) : par(n), rank(n, 0), sz(n, 1) {
        rep(i, n) par[i] = i; // 全てが根であるとして初期化
    }

    // x が属する木の根を求める
    int find(const int x) {
        if (par[x] == x)
            return x;
        return par[x] = find(par[x]);
    }

    // x と y を併合する
    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y)
            return;

        if (rank[x] < rank[y]) {
            par[x] = y;
            sz[y] += sz[x];
        } else {
            par[y] = x;
            sz[x] += sz[y];
            if (rank[x] == rank[y]) {
                ++rank[x];
            }
        }
    }

    // x と y が同じ木に属するか
    bool same(const int x, const int y) { return find(x) == find(y); }

    int size(const int x) { return sz[find(x)]; }

private:
    vint par;  // 親
    vint rank; // ランク（根からの距離）
    vint sz;   // 木の要素数
};

void Main() {
    int n = in(), q = in();
    UnionFind uf(n);
    while (q--) {
        int t = in(), u = in(), v = in();
        if (t)
            out(uf.same(u, v));
        else
            uf.unite(u, v);
    }
}

