int parent[200005];
int R[200005];

int find(int a){
    if(parent[a]==a) return a;
    return parent[a] = find(parent[a]);
}

void merge(int a, int b){
    a = find(a);
    b = find(b);

    if(a==b) return;

    if(R[a] > R[b]){
        parent[b] = a;
        R[a] += R[b];
    }
    else{
        parent[a] = b;
        R[b] += R[a];
    }
}

void init_par(int n){
    fo(i,n){
        R[i] = 1;
        parent[i] = i;
    }
}

