  while(q-- > 0) {
    int t,u,v; scanf("%d %d %d", &t, &u, &v);
    if(t == 0) uf.unite(u, v);
    else printf("%d\n", (uf.same(u, v) ? 1 : 0));
  }
  return 0;
}

