        // cerr << "move " << q << ' ' << x << '\n';
        p[q] = p[x];
        v[p[x]].pb(q);
//        (col[q] += col_shift) %= 3;
    }
    v[src].clear();
}

int work(int go) {
    for (int i = 0; i < n; i++) {
        p[i] = i;
        v[i].clear();
        v[i].pb(i);
        col[i] = 0;
    }

    for (int i = 0; i < m; i++) {
        int u, v, st;
        u = games[i].fi.fi;
        v = games[i].fi.se;
        st = games[i].se;

        if (u == go or v == go)
