    void set(int p, S x) {
        assert(0 <= p && p < _n);
        p += size;
        for(int i = log; i >= 1; i--)
            push(p >> i);
        d[p] = x;
        for(int i = 1; i <= log; i++)
            update(p >> i);
    }
    S get(int p) {
        assert(0 <= p && p < _n);
        p += size;
        for(int i = log; i >= 1; i--)
            push(p >> i);
        return d[p];
    }
