class Set{
    vector<int> parent;
    public:

    Set(int n)
    {
        for(int i = 0;i<n;i++)
        {
            parent.push_back(i);
        }
    }

    int getSuperParent(int x)
    {
        if(x==parent[x])
        {
            return x;
        }
        return parent[x] = getSuperParent(parent[x]);
    }

    void join(int a, int b)
    {
        a = getSuperParent(a);
        b = getSuperParent(b);
        if(a!=b)
        {
            parent[b] = a;
        }
    }

    void ifConnected(int a, int b)
    {
        a = getSuperParent(a);
        b = getSuperParent(b);
        if(a==b)
        {
            cout<<1<<endl;
        }
        else{
            cout<<0<<endl;
        }
    }
};


