  }
  void unite(int x, int y) {
    x = find(x), y = find(y);
    if (x == y)return;
    if (ran[x] < ran[y]) {
      par[x] = y; sz[y] += sz[x];
    }
    else {
      par[y] = x; sz[x] += sz[y];
      if (ran[x] == ran[y])ran[x]++;
    }
  }
  bool same(int x, int y) {
    return find(x) == find(y);
  }
  int num(int x) { return sz[find(x)]; }
};

