class dsu{
private:
    int* parent;
    int* size;

    int root(int x){
        while(x!=parent[x]){
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
public:
    int components;
    dsu(int n){
        parent = new int [n];
        size = new int [n];
        components = n ;
        for(int i = 0 ; i<n ; i++){
            parent[i] = i ;
            size[i] = 1;
        }
    }
    bool find(int x , int y){
        return root(x)==root(y);
    }
    void join(int x , int y){
        int i = root(x);
        int j = root(y);
        if(i==j){
            return ;
        }
        else{
            components--;
            if(size[i]<size[j]){
                parent[i] = j;
                size[j]+=size[i];
                size[i] = 0;
            }
            else{
                parent[j] = i ; 
                size[i]+=size[j];
                size[j] = 0;
            }
        }
    }
    int sz(int x){
        return size[x];
    }
};


