  */
  class UnionFind {
    public:
    UnionFind() {}
    UnionFind(int n) :
        parent(n, -1), rank(n, 0) {}

    int find(int a) {
      if (parent[a] == -1)
        return a;
      else
        return parent[a] = find(parent[a]);
    }

    void unite(int a, int b) {
      a = find(a);
      b = find(b);

      if (a == b) return;
      if (rank[a] == rank[b]) {
        parent[a] = b;
        rank[b]++;
        return;
      }
      if (rank[a] > rank[b]) swap(a, b);
      parent[a] = b;
    }

    private:
    vector<int> parent, rank;
  };
