class UnionFind {
  public:
    UnionFind() : _n{0}{}
    UnionFind(int n) : _n{n}, pr(n, -1){}

    int merge(int a, int b) {
      assert(0 <= a && a < _n);
      assert(0 <= b && b < _n);
      a = leader(a);
      b = leader(b);
      if (a == b) return a;
      if (-pr[a] < -pr[b]) swap(a, b);
      pr[a] += pr[b];
      pr[b] = a;
      return a;
    }

    bool same(int a, int b) {
      assert(0 <= a && a < _n);
      assert(0 <= b && b < _n);
      return leader(a) == leader(b);
    }

    int leader(int a) {
      assert(0 <= a && a < _n);
      return (pr[a]<0) ? a : (pr[a]=leader(pr[a]));
    }

  private:
    int _n;
    vector<int> pr;
};

