template<class Cap>
class MaxFrow {
public:
	//コンストラクタ
	MaxFrow() : N(0) {}
	MaxFrow(int n): N(n), G(n) {}



	//from から to への 容量 cap の辺を追加する。
	//0-indexed で、何番目に追加された辺かを返す。
	int add_edge(int from, int to, Cap cap) {
		assert(0 <= from && from < N);
		assert(0 <= to && to < N);
		assert(0 <= cap);
		int m = (int)(pos.size());
		pos.push_back({ from, (int)(G[from].size()) });
		G[from].push_back(edge1{ to, (int)(G[to].size()), cap });
		G[to].push_back(edge1{ from, (int)(G[from].size()) - 1, 0 });
		return m;
	}



	struct edge1 {
		int to;  //行先
		int rev; //逆辺
		Cap cap; //容量
	};



	struct edge2 {
		int from;
		int to;  //行先
		Cap cap; //容量
		Cap flow; //流量
	};



	//i番目に追加された辺を返す。
	edge2 get_edge(int i) {
		int m = (int)(pos.size());
		assert(0 <= i && i < m);

		auto _e = G[pos[i].first][pos[i].second];
		auto _rev = G[_e.to][_e.rev];
		return edge2{ pos[i].first, _e.to, _e.cap + _rev.cap, _rev.cap };
	}



	//増加パスをDFSで探す
	Cap dfs(int v, const int t, Cap flow, vector<bool>seen) {
		if (v == t) return flow;
		seen[v] = true;

		for (int i = 0; i < (int)(G[v].size()); i++) {
			edge1 e = G[v][i];
			if (seen[e.to] || e.cap <= 0) continue;
			int res = dfs(e.to, t, min(flow, e.cap));

			if (res > 0) {
				e.cap -= res;
				G[e.to][e.rev].cap += res;
				return res;
			}
		}
		return 0;
	};



	int max_flow(int s, int t) {
		int res = 0;
		while (true) {
			vector<bool> seen(N, false);
			int flow = dfs(s, t, INF, seen);
			if (flow == 0) return res;
			res += flow;
		}
	}



private:
	int N;

	//i番目の辺を保存する。{from_i, G[from_i] の何番目の要素か}
	std::vector<std::pair<int, int>> pos;
	std::vector<std::vector<edge1>> G;
};




