  for (int i = 0; i < Q; ++i) {
    cin >> t >> u >> v;

    if (t == 0) {
      uf.unite(u, v);
    } else {
      if (uf.same(u, v)) {
        cout << 1 << endl;
      } else {
        cout << 0 << endl;
      }
    }
  }

  return 0;
}

