struct DSU{
 int N;
 struct Node{ int d; int p; };
 vector<Node> V;
 void init(int n){
  N=n; V.resize(N);
  rep(i,N) V[i]={0,i};
 }
 int root(int a){
  if(a==V[a].p) return a;
  return V[a].p = root(V[a].p);
 }
 void unite(int a,int b){
  a=root(a); b=root(b);
  if(V[a].d<V[b].d){ V[a].p = a; }
  else if(V[a].d>V[b].d){ V[b].p = a; }
  else{ V[a].p = b; ++V[b].d; }
 }
};

