using namespace std;

struct UnionFind {
	vector<int> par;

	UnionFind(int n) : par(n, -1) { }
	void init(int n) { par.assign(n, -1); }

	int root(int x) {
		if (par[x] < 0) return x;
		else return par[x] = root(par[x]);
	}

	bool issame(int x, int y) {
		return root(x) == root(y);
	}

	bool merge(int x, int y) {
		x = root(x); y = root(y);
		if (x == y) return false;
		if (par[x] > par[y]) swap(x, y); // merge technique
		par[x] += par[y];
		par[y] = x;
		return true;
	}

	int size(int x) {
		return -par[root(x)];
	}
};

int main() {
	int N, Q;
	scanf("%d %d", &N, &Q);
	UnionFind uf(N);
	for (int n = 0; n < Q; ++n) {
		int t, u, v;
		scanf("%d %d %d", &t, &u, &v);
		if (0 == t) {
			uf.merge(u, v);
		}
		else {
			if (uf.issame(u,v)) {
				printf("1\n");
			}
			else {
				printf("0\n");
			}
		}
	}
	return 0;
}

