using namespace std;


class UnionFind {
private:
  vector<int> r;
public:
  UnionFind(int N) {
    r.assign(N, -1);
  }

  int root(int x) {
    return (r[x]<0) ? x : root(r[x]);
  }

  bool connected(int x, int y) {
    return root(x) == root(y);
  }

  void merge(int x, int y) {
    x = root(x);
    y = root(y);

    if (r[x] < r[y]) swap(x, y);
    r[x] += r[y];
    r[y] = x;
  }
};

int main() {
  int N, Q;
  cin >> N >> Q;
  UnionFind U{N};
  while (Q--) {
    int t, u, v;
    cin >> t >> u >> v;
    if (!t) {
      U.merge(u, v);
    } else {
      cout << U.connected(u, v) << endl;
    }
  }
  return 0;
}

