struct UnionFind {
    vi par,size;
    UnionFind(int n) {
        par.resize(n);
        size.resize(n,1);
        rep(i, n) par[i]=i;
    }
    bool same(int x,int y) {
        return find(x)==find(y);
    }
    int consize(int k) {
        return size[find(k)];
    }
    int find(int k) {
        if(par[k]==k) return k;
        return par[k]=find(par[k]);
    }
    bool unite(int x,int y) {
        if(same(x,y)) return false;
        if(consize(x)<consize(y)) {
            par[find(x)]=find(y);
            size[y]+=size[x];
        }
        else {
            par[find(y)]=find(x);
            size[x]+=size[y];
        }
        return true;
    }
};
