int sum(int l, int r) {
	l+=n, r+=n;
	long long ans = 0;
	while(l<r) {
		if(l&1) ans += st[l++];
		if(r&1) ans += st[--r];
		l>>=1, r>>=1;
	}
	return ans;
}

