class unionfind {
  vector<int> par;

public:
  unionfind(int n) {
    for (int i = 0; i < n; i++) {
      par.push_back(i);
    }
  }

  int find(int n) {
    if (par.at(n) == n) return n;
    return par.at(n) = find(par.at(n));
  }

  void merge(int m, int n) {
    m = find(m);
    n = find(n);
    par.at(m) = n;
  }
};

