// UnionFind
class UF{
public:
    int n;
    vector<int> parent;
    vector<int> size;

    UF(int n){
        parent.resize(n);
        size.resize(n);
        for(int i = 0; i < n; i++){
            parent[i] = i;
            size[i] = 1;
        }
    }

    bool unite(int a, int b){
        int parentA = find(a);
        int parentB = find(b);

        if(parentA == parentB){
            return false;
        }
        else{
            int sizeA = size[parentA];
            int sizeB = size[parentB];
            if(sizeA < sizeB){
                parent[parentA] = parentB;
                size[parentB] += sizeA;
            }
            else{
                parent[parentB] = parentA;
                size[parentA] += sizeB;
            }
            return true;
        }
    }

    int find(int node){
        int p = parent[node];
        if(p == node){
            return p;
        }
        else{
            int newP = find(p);
            parent[node] = newP;
            return newP;
        }
    }
};


int main(){

    int N, Q;
    cin >> N >> Q;

    UF uf(N);

    for(int i = 0; i < Q; i++){
        int t, u, v;
