        if(t == 0){
            uf.unite(u, v);
        }
        else{   // t == 1
            if(uf.find(u) == uf.find(v)){
                cout << 1 << endl;
            }
            else{
                cout << 0 << endl;
            }
        }
    }

    return 0;
}

