	int find(int v){
		return (par[v]==v)? v: (par[v]=find(par[v]));
	}
	explicit UF(int N):par(N),num(N,1){
		iota(all(par),0);
	}
	void unite(int u,int v){
		u=find(u),v=find(v);
		if(u==v)return;
		if(num[u]<num[v])swap(u,v);
		num[u]+=num[v];
		par[v]=u;
	}
	bool same(int u,int v){
		return find(u)==find(v);
	}
	bool ispar(int v){
		return v=find(v);
	}
	int size(int v){
		return num[find(v)];
	}
};
int main(){
    int n,q;
    cin>>n>>q;
    UF uf(n);
    while(q--){
        int t,a,b;
        cin>>t>>a>>b;
        if(t){
            cout<<uf.same(a,b)<<"\n";
        }else{
            uf.unite(a,b);
        }
    }
}

