    mf_graph<int> g(t+1);
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (S[i][j] == '#')
                continue;
            if ((i+j) % 2 == 0)
                g.add_edge(s, i*m+j, 1);
            else
                g.add_edge(i*m+j, t, 1);
            if (j+1 < m && S[i][j+1] =='.') {
                if ((i+j) % 2 == 0)
                    g.add_edge(i*m+j, i*m+j+1, 1);
                else
                    g.add_edge(i*m+j+1, i*m+j, 1);
            }
            if (i+1 < n && S[i+1][j] =='.') {
                if ((i+j) % 2 == 0)
                    g.add_edge(i*m+j, (i+1)*m+j, 1);
                else
                    g.add_edge((i+1)*m+j, i*m+j, 1);
            }
        }
    }

    g.flow(s, t);
    int cnt = 0;
    auto ans = S;
    auto E = g.edges();
    for (auto e : E) {
        int a = e.from, b = e.to;
        if (a == s || a == t || b == s || b == t || e.flow != 1)
            continue;
        cnt++;
        if (a > b)
            swap(a, b);
        if (a+1 == b) {
            ans[a/m][a%m] = '>';
            ans[b/m][b%m] = '<';
        }
        else {
            ans[a/m][a%m] = 'v';
            ans[b/m][b%m] = '^';
        }
    }

    cout << cnt << endl;
    for (auto ai : ans)
        cout << ai << endl;

    return 0;
}

