struct UnionFind {
	V<int> p, r;
	int gn;
	UnionFind(int n = 0) : p(n, -1), r(n, 1), gn(n) {}
	void merge(int a, int b) {
		int x = group(a), y = group(b);
		if (x == y) return; // same
		gn--;
		if (r[x] < r[y]) {
			p[x] = y;
		}
		else {
			p[y] = x;
			if (r[x] == r[y]) r[x]++;
		}
	}
	int group(int a) {
		if (p[a] == -1) return a;
		return p[a] = group(p[a]);
	}
	bool same(int a, int b) {
		return group(a) == group(b);
	}
};

