        while (i + Z[i] < S.size() && S[Z[i]] == S[i + Z[i]])
            Z[i] ++;
        if (last < i + Z[i]) { last = i + Z[i]; start = i; }
    }
    Z[0] = n;
    return Z;
}

//---------------------------------------------------------------
// 二部グラフ判定(O(E))  edge -> リスト
//---------------------------------------------------------------
bool is_bipartite(vvll edge)
{
    ll N = edge.size();
    vll color(N, -1);
    color[0] = 0;
    queue<ll> Q;
    Q.push(0);
    while (!Q.empty())
    {
        ll now = Q.front();
        Q.pop();

        for (int i : edge[now])
        {
            if (color[i] == -1)
            {
                color[i] = (color[now] == 0 ? 1 : 0);
                Q.push(i);
            }
            else if (color[i] == color[now])
            {
                return false;
            }
        }
    }
    return true;
}

//---------------------------------------------------------------
// セグメント木
//---------------------------------------------------------------
class SegmentTree
{
public:

    const ll SEG_LEN = 1 << 19;
    vector<set<ll>> seg;
    ll s;

    SegmentTree(vll A) : seg(SEG_LEN * 2, set<ll>({})) {
        s = A.size();

        for (int i = 0; i < A.size(); i++)
        {
            seg[i + SEG_LEN] = { A[i] };
        }



        for (int i = 0; i < A.size(); i++)
        {
            ll pos = i + SEG_LEN;
            while (true)
            {
                pos /= 2;
                if (pos <= 0) break;

                if (seg[pos * 2 + 1].size() < seg[pos * 2].size())
                {
                    seg[pos] = seg[pos * 2];

                    for (auto itr = seg[pos * 2 + 1].begin(); itr != seg[pos * 2 + 1].end(); ++itr) {

                        seg[pos].insert(*itr);
                    }
                }
                else
                {
                    seg[pos] = seg[pos * 2 + 1];

                    for (auto itr = seg[pos * 2].begin(); itr != seg[pos * 2].end(); ++itr) {

                        seg[pos].insert(*itr);
                    }
                }

            }
        }


    }

    ll seg_max(ll left, ll right)
    {
        left += SEG_LEN;
        right += SEG_LEN + 1;

        set<ll> ret = {};
        vbool used(s + 1, false);

        while (left < right)
        {
            while (left % 2 == 1)
            {
                if (seg[left].size())
                {
                    for (auto itr = seg[left].begin(); itr != seg[left].end(); ++itr) {
                        if (!used[*itr]) {
                            ret.insert(*itr);
                            used[*itr] = true;
                        }
                    }
                }
                left++;
            }
            while (right % 2 == 1)
            {
                if (seg[right - 1].size())
                {
                    for (auto itr = seg[right - 1].begin(); itr != seg[right - 1].end(); ++itr) {
                        if (!used[*itr]) {
                            ret.insert(*itr);
                            used[*itr] = true;
                        }
                    }
                }
                right--;
            }

            left /= 2;
            right /= 2;
        }

        return ret.size();
    }

};


