        res += to_string(q.top());
        copy.push(q.top());
        q.pop();
    }

    swap(q, copy);
    res += "}";
    return res;
}

template<typename T>
string to_string(queue<T>& q){
    queue<T> copy;
    bool first = true;
    string res = "{";
    while(!q.empty()){
        if (!first) {
            res += ", ";
        }
        first = false;
        res += to_string(q.front());
        copy.push(q.front());
        q.pop();
    }

    swap(q, copy);
    res += "}";
    return res;
}

