class UnionFind
{
public:
    //隕ｪ縺ｮ逡ｪ蜿ｷ繧呈�ｼ邏阪☆繧九�りｦｪ縺�縺｣縺溷�ｴ蜷医��-(縺昴��髮��粋縺ｮ繧ｵ繧､繧ｺ)
    vector<int> Parent;

    //菴懊ｋ縺ｨ縺阪��Parent縺ｮ蛟､繧貞��縺ｦ-1縺ｫ縺吶ｋ
    //縺薙≧縺吶ｋ縺ｨ蜈ｨ縺ｦ繝舌Λ繝舌Λ縺ｫ縺ｪ繧�
    UnionFind(int N)
    {
        Parent = vector<int>(N, -1);
    }

    //A縺後←縺ｮ繧ｰ繝ｫ繝ｼ繝励↓螻槭＠縺ｦ縺��ｋ縺玖ｪｿ縺ｹ繧�
    int root(int A)
    {
        if (Parent[A] < 0)
            return A;
        return Parent[A] = root(Parent[A]);
    }

    //閾ｪ蛻����縺��ｋ繧ｰ繝ｫ繝ｼ繝励��鬆らせ謨ｰ繧定ｪｿ縺ｹ繧�
    int size(int A)
    {
        return -Parent[root(A)]; //隕ｪ繧偵→縺｣縺ｦ縺阪◆縺Ь
    }
    bool issame(int x, int y)
    {
        return root(x) == root(y);
    }
    //A縺ｨB繧偵￥縺｣莉倥￠繧�
    bool connect(int A, int B)
    {
        //A縺ｨB繧堤峩謗･縺､縺ｪ縺舌��縺ｧ縺ｯ縺ｪ縺上�〉oot(A)縺ｫroot(B)繧偵￥縺｣縺､縺代ｋ
        A = root(A);
        B = root(B);
        if (A == B)
        {
            //縺吶〒縺ｫ縺上▲縺､縺��※繧九°繧峨￥縺｣莉倥￠縺ｪ縺�
            return false;
        }

        //螟ｧ縺阪＞譁ｹ(A)縺ｫ蟆上＆縺��⊇縺�(B)繧偵￥縺｣莉倥￠縺溘＞
        //螟ｧ蟆上′騾��□縺｣縺溘ｉ縺ｲ縺｣縺上ｊ霑斐＠縺｡繧��≧縲�
        if (size(A) < size(B))
            swap(A, B);

        //A縺ｮ繧ｵ繧､繧ｺ繧呈峩譁ｰ縺吶ｋ
        Parent[A] += Parent[B];
        //B縺ｮ隕ｪ繧但縺ｫ螟画峩縺吶ｋ
        Parent[B] = A;

        return true;
    }
};

