#include <bits/stdc++.h>
using namespace std;

class dsu {
  int N;
  vector<int> PS;
public:
  dsu() : N(0) {}
  dsu(int n) : N(n), PS(n, -1) {}
  int merge(int a, int b) {
    assert(0 <= a && a < N);
    assert(0 <= b && b < N);
    int x = leader(a), y = leader(b);
    if (x == y) return x;
    if (-PS.at(x) < -PS.at(y)) swap(x, y);
    PS.at(x) += PS.at(y);
    PS.at(y) = x;
    return x;
  }
  bool same(int a, int b) {
    assert(0 <= a && a < N);
    assert(0 <= b && b < N);
    return leader(a) == leader(b);
  }
  int leader(int a) {
    assert(0 <= a && a < N);
    if (PS.at(a) < 0) return a;
    return PS.at(a) = leader(PS.at(a));
  }
  int size(int a) {
    assert(0 <= a && a < N);
    return -PS.at(leader(a));
  }
  vector<vector<int>> groups() {
    vector<int> leader_buf(N), group_size(N);
    for (int i = 0; i < N; i++) {
      leader_buf.at(i) = leader(i);
      group_size.at(leader_buf.at(i))++;
    }
    vector<vector<int>> result(N);
    for (int i = 0; i < N; i++) {
      result.at(i).reserve(group_size.at(i));
    }
    for (int i = 0; i < N; i++) {
      result.at(leader_buf.at(i)).push_back(i);
    }
    result.erase(
      remove_if(result.begin(), result.end(), [&](const vector<int>& v) { return v.empty(); }),
      result.end()
    );
    return result;
  }
};

int main() {
  cin.tie(nullptr);
  ios_base::sync_with_stdio(false);
  int N, Q;
  cin >> N >> Q;
  dsu D(N);
  for (int i = 0; i < Q; i++) {
    int t, u, v;
    cin >> t >> u >> v;
    if (t)
      cout << D.same(u, v) << "\n";
    else
      D.merge(u, v);
  }
}

