struct UnionFind {
    vector<int> par;
    vector<long long> siz;
    long long psiz;

    UnionFind(int N) : par(N),siz(N,1LL),psiz(N) {
        for(int i = 0; i < N; i++) par[i] = i;
    }
    int root(int x) {
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }
    void unite(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) return;
        if(siz[rx] < siz[ry]) swap(rx,ry);
        siz[rx] += siz[ry];
        psiz -= siz[ry];
        par[ry] = rx;
    }
    bool same(int x, int y) {
        return root(x) == root(y);
    }
    long long size(int x){
        return siz[root(x)];
    }
    long long psize() {
        return psiz;
    }
};

int main(){
    int n,q;
    cin >> n >> q;
    UnionFind tree(n);
    rep(i,q){
