int Unionfind::find(int x) {
    while (p[x] != x) {
        p[x] = p[p[x]];
        x = p[x];
    }
    return x;
}

void Unionfind::unite(int x, int y) {
    x = Unionfind::find(x);
    y = Unionfind::find(y);
    if (x != y) {
        p[x] = y;
    }
}

bool Unionfind::isunion(int x, int y) {
    return Unionfind::find(x) == Unionfind::find(y);
}

