struct disjoint_set {
    int n;
    vector<int> d;

    disjoint_set() : n(0) {}
    disjoint_set(int sz) : n(sz), d(n, -1) {}

    int find(int a) {
        assert(0 <= a && a < n);
        if (d[a] < 0) return a;
        return d[a] = find(d[a]);
    }

    int unite(int a, int b) {
        assert(0 <= a && a < n);
        assert(0 <= b && b < n);
        int x = find(a), y = find(b);
        if (x == y) return x;
        if (-d[x] < -d[y]) swap(x, y);
        return d[y] = x;
    }

    bool same(int a, int b) {
        assert(0 <= a && a < n);
        assert(0 <= b && b < n);
        return find(a) == find(b);
    }

    int size(int a) {
        assert(0 <= a && a < n);
        return -d[find(a)];
    }

    vector<vector<int>> groups() {
        vector<int> f(n), g(n);
        for_range(i, 0, n) {
            f[i] = find(i);
            g[f[i]]++;
        }
        vector<vector<int>> r(n);
        for_range(i, 0, n) r[i].reserve(g[i]);
        for_range(i, 0, n) r[f[i]].push_back(i);
        r.erase(remove_if(r.begin(), r.end(),
                          [&](vector<int>& v) { return v.empty(); }),
                r.end());
        return r;
    }
};

