ll n, m;

void ansPrint(int fromid, int toid){
    int fx = fromid / m, fy = fromid % m;
    int tx = toid / m, ty = toid % m;
    if (fx == tx) {
        s[fx][min(fy, ty)] = '>';
        s[fx][max(fy, ty)] = '<';
    } else {
        s[min(fx, tx)][fy] = 'v';
        s[max(fx, tx)][fy] = '^';
    }
}

void solve() {
    cin >> n >> m;
    mf_graph<ll> graph(n * m + 2);
    ll maxi = n * m;
    for (int i = 0; i < n; i++) {
        cin >> s[i];
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (s[i][j] == '#') continue;
            int id = i * m + j;
            bool flag = ((i + j) % 2 == 1);
            if (flag) {
                graph.add_edge(maxi, id, 1);
                for (int k = 0; k < 4; k++) {
                    ll nx = i + dx[k], ny = j + dy[k];
                    if (nx < 0 || ny < 0 || n <= nx || m <= ny) continue;
                    if (s[nx][ny] == '#') continue;
                    int nid = nx * m + ny;
                    graph.add_edge(id, nid, 1);
                }
            } else {
                graph.add_edge(id, maxi + 1, 1);
            }
        }
    }
    ll res = graph.flow(maxi, maxi + 1);
    p(res);

    auto E = graph.edges();
    for (auto edge : E) {
        int fromid = edge.from, toid = edge.to;
        if (fromid == maxi || toid == maxi + 1) continue;
        if (edge.flow == 0) continue;
        ansPrint(fromid, toid);
    }

    for(int i=0;i<n;i++){
        p(s[i]);
    }
    return;
}

