// Implement (union by size) + (path compression)
// Reference:
// Zvi Galil and Giuseppe F. Italiano,
// Data structures and algorithms for disjoint set union problems
// -> 一部改変(2020/09/08).
struct DSU{
public:
    DSU() : _n(0){}
    DSU(int n) : _n(n), parent_or_size(n, -1){}
    int merge(int a, int b){
        assert(0 <= a && a < _n);
        assert(0 <= b && b < _n);
        int x = root(a), y = root(b);
        if(x == y) return x;
        if(-parent_or_size[x] < -parent_or_size[y]) swap(x, y);
        parent_or_size[x] += parent_or_size[y];
        parent_or_size[y] = x;
        return x;
    }

    bool same(int a, int b){
        assert(0 <= a && a < _n);
        assert(0 <= b && b < _n);
        return root(a) == root(b);
    }

    int root(int a){
        assert(0 <= a && a < _n);
        if(parent_or_size[a] < 0) return a;
        return parent_or_size[a] = root(parent_or_size[a]);
    }

    int size(int a){
        assert(0 <= a && a < _n);
        return -parent_or_size[root(a)];
    }

    vvi groups(){
        vi buf(_n), group_size(_n);
        rep(i, _n){
            buf[i] = root(i);
            group_size[buf[i]]++;
        }
        vvi result(_n);
        rep(i, _n) result[i].reserve(group_size[i]);
        rep(i, _n) result[buf[i]].pb(i);
        result.erase(
            remove_if(all(result), [&](const vi& v) { return v.empty(); }), result.end());
        return result;
    }

private:
    int _n;
    // root node: -1 * component size
    // otherwise: parent
    vi parent_or_size;
};

int main(){

    // 1. 入力情報.
    int N, Q;
    scanf("%d %d", &N, &Q);

    // 2. クエリ回答.
    DSU uf(N);
    rep(i, Q){
        int t, u, v;
        scanf("%d %d %d", &t, &u, &v);
        if(t) printf("%d\n", uf.same(u, v) ? 1 : 0);
        else  uf.merge(u, v);
    }
    return 0;

}

