vector<ll> solver(ll N, ll Q, vector<ll> t, vector<ll> u, vector<ll> v) {
    dsu d(N);
    vector<ll> ans;
    for (int i = 0; i < Q; i++) {
        if (t[i] == 0) {
            d.merge(u[i], v[i]);
        } else {
            ans.push_back(d.same(u[i], v[i]));
        }
    }
    return ans;
}

