struct DSU{
 int N;
 struct Node{ int d; int p; };
 vector<Node> V;
 void init(int n){
  N=n; V.resize(N);
  rep(i,N) V[i]={0,i};
 }
 int root(int a){
  if(a==V[a].p) return a;
  return V[a].p = root(V[a].p);
 }
 void unite(int a,int b){
  a=root(a); b=root(b);
  if(V[a].d<V[b].d){ V[a].p = b; }
  else if(V[a].d>V[b].d){ V[b].p = a; }
  else{ V[a].p = b; ++V[b].d; }
 }
};

int main(){
 int N,Q; scanf("%d%d",&N,&Q);
 DSU G; G.init(N);
 rep(q,Q){
  int c; scanf("%d",&c);
  if(c==0){
   int x,y; scanf("%d%d",&x,&y);
   G.unite(x,y);
  }
  if(c==1){
   int x,y; scanf("%d%d",&x,&y);
   printf((G.root(x)==G.root(y)) ? "1\n" : "0\n");
  }
 }
 return 0;
}

