class UnionFind {
	vector<int> par;
public:
	UnionFind(int n) : par(n, -1) { }
	void init(int n) { par.assign(n, -1); }
	lint root(int x) {//根を出す
		if (par[x] < 0) return x;
		else return par[x] = root(par[x]);
	}
	bool same(int x, int y) {//同じ集合なのかを調べる
		return root(x) == root(y);
	}
	bool unite(int x, int y) {//xの根とyの根をつなげる
		x = root(x); y = root(y);
		if (x == y) return false;
		if (par[x] > par[y]) swap(x, y);
		par[x] += par[y];
		par[y] = x;
		return true;
	}
	int size(int x) {
		return -par[root(x)];
	}
};
int n, q;

int main(void) {
	cin >> n >> q;
	UnionFind u(n);
	for (int i = 0; i < q; i++) {
		int a, b, c; cin >> a >> b >> c;
		if (a == 0) {
			u.unite(b, c);
		}
		else {
			if (u.same(b, c)) cout << 1 << endl;
			else cout << 0 << endl;
		}
	}

	return 0;
}

#include <iostream>
