#include <iostream>
#include <vector>
using namespace std;

struct UnionFind
{
    vector<int> par, rank;

    UnionFind(int n){
        par.resize(n);
        rank.resize(n);
        for(int i = 0; i < n; i++){
            par[i] = i;
            rank[i] = 0;
        }
    }

    int find(int i){
        if(i == par[i]) return i;
        return par[i] = find(par[i]);
    }

    bool same(int i, int j){
        return find(i) == find(j);
    }

    void unite(int i, int j){
        if(same(i, j)) return;
        i = find(i), j = find(j);
        if(rank[i] < rank[j]) par[i] = j;
        else{
            par[j] = i;
            if(rank[i] == rank[j]) rank[i]++;
        }
    }
};

int main()
{
    int n, q;
    cin >> n >> q;
    UnionFind uf(n);
    while(q--){
        int t, u, v;
        cin >> t >> u >> v;
        if(t) cout << uf.same(u, v) << endl;
        else uf.unite(u, v);
    }
}

