	{
		int a, b, c;
		cin >> a >> b >> c;
		if(a == 0)
		{
			union_sets(b + 1, c + 1);
		}
		else
		{
			if(find_set(b+1) == find_set(c+1))
			{
				cout << '1' << endl;
			}
			else
			{
				cout << '0' << endl;
			}
		}
	}
