class UnionFind{
public:
    vector<int> v;

    UnionFind(int n){
        v.assign(n,-1);
    }

    int find(int x){
        if(v[x]<0) return x;
        v[x]=find(v[x]);
        return v[x];
    }

    bool same(int a,int b){
        if(find(a)==find(b)) return true;
        return false;
    }

    void union_u(int a,int b){
        if(same(a,b)) return;
        int a_p=find(a),b_p=find(b);
