    REP(i,Q){
        ll t, a, b;
        cin >> t >> a >> b;

        if(t==0){
            tree.unite(a, b);
        }
        else{
            if(tree.same(a,b)==true){
                cout << 1 << endl;
            }
            else{
                cout << 0 << endl;
            }
        }
    }
}

