using namespace std;
const int MAX_N = 200000;
int Par[MAX_N],Rank[MAX_N] = {};
int N;
void init(){
  int i;
  for(i=0;i<N;i++){
    Par[i] = i;
  }
}
int find(int x){//根元探し
  if(Par[x] == x) return x;
  else{
    Par[x] = find(Par[x]);
    return Par[x];
  }
}
bool unite(int x,int y){//結合
  x = find(x);y = find(y);
  if(x == y) return false;//すでに同じ木ならばfalse
  if(Rank[x] < Rank[y]) swap(x,y);
  Par[y] = x;
  if(Rank[x] == Rank[y]) Rank[x]++;
  return true;
}
bool same(int x,int y){//同じ木に含まれているか
  return find(x) == find(y);
}
int main(){
  int Q,i,t,u,v;scanf("%d%d",&N,&Q);
  init();
  for(i=0;i<Q;i++){
    scanf("%d%d%d",&t,&u,&v);
    if(t == 0) unite(u,v);
    else printf(same(u,v) ? "1\n":"0\n");
  }
}

