class UnionFind {
	mutable std::vector<int> parent;
public:
	UnionFind(const int _size) : parent(_size, -1) {};
	int find_root(const int a) const {
		return (parent[a] < 0) ? a : parent[a] = find_root(parent[a]);
	}
	bool is_same(const int a, const int b) const {
		return find_root(a) == find_root(b);
	}
	void merge(int a, int b) {
		a = find_root(a);
		b = find_root(b);
		if (a == b) return;
		if (parent[a] > parent[b]) std::swap(a, b);
		parent[a] += parent[b];
		parent[b] = a;
	}
	int size_of(const int a) const { return -parent[find_root(a)]; }
};

