    std::vector<std::vector<int>> ls;
    {
        int t, u, v;
        for(int i(0); i < Q; ++i){
            std::cin >> t >> u >> v;
            if(t){
                std::cout << d.same(u, v) << "\n";
            }else d.unit(u, v);
        }
    }
    return 0;
}

