int find(int u){
    if(data[u]<0) return u;
    return data[u]=find(data[u]);
}

bool union_join(int u, int v){
    int a=find(u);
    int b=find(v);
    if(a==b) return false;
    if(a>b)swap(a, b);
    data[a]+=data[b];
    data[b]=a;
    return true;
}

bool same_set(int u, int v){
    return find(u)==find(v);
}

int main() {
    cin>>n>>m;
    memset(data, -1, sizeof(data));
    while(m--){
        cin>>op>>u>>v;
        if(op==0){
            union_join(u, v);
        }else{
            if(same_set(u, v)) cout<<1<<endl;
            else cout<<0<<endl;
        }
    }
    return 0;
}

