    union_find_tree uf(N);
    rep(i, Q) {
        int t = io.getint(), u = io.getint(), v = io.getint();
        if (t == 0) { uf.unite(u, v); }
        else { io.putint(uf.are_same(u, v)), io.putchar('\n'); }
    }
}

