int findRoot(int u){
  while(u!=par[u]){
    u=par[u];
  }
  return u;
}
void merge(int u,int v){
  int Pu = findRoot(u);
  int Pv = findRoot(v);
  if(Pu==Pv)return;
  if(sz[Pu]>=sz[Pv]){
    par[Pv]=Pu;
    sz[Pu]+=sz[Pv];
  }else{
    par[Pu]=Pv;
    sz[Pv]+=sz[Pu];
  }
}
