struct dat{
    int l;
    int r;
    int id;
};

using T=ll;

using E=ll;

T f(T a,T b){
    return min(a,b);
}

T g(E a,T b){
    return a+b;
}

E h(E a,E b){
    return a+b;
}

T ti(){
    return INF;
}

E ei(){
    return 0;
}

bool check(T x){
    return x>0LL;
}

int main(){

    std::ifstream in("text.txt");
    std::cin.rdbuf(in.rdbuf());
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N,Q;cin>>N>>Q;
    vector<int> A(N);
    vector<pair<int,int>> B(N);
    vector<ll> def(N);

    for(int i=0;i<N;i++){
        cin>>A[i];
        A[i]--;
        B[i].fi=i-A[i];
        B[i].se=i;

        def[i]=B[i].fi;
        if(def[i]<0) def[i]=INF-3;
    }

    atcoder::lazy_segtree<T,f,ti,E,g,h,ei> seg(def);

    vector<dat> S(Q);
    for(int i=0;i<Q;i++){
        cin>>S[i].l>>S[i].r;
        S[i].id=i;

        S[i].r=N-S[i].r;
    }

    vector<int> ans(Q);

    sort(all(S),[](auto a,auto b){
        return a.l>b.l;
    });

    atcoder::fenwick_tree<ll> cnt(N);

    int id=0;

    for(int i=N-1;i>=0;i--){
        if(B[i].fi==0){
            seg.apply(i+1,N,-1);
            seg.apply(i,i+1,1e8);
            cnt.add(i,1);

            while(1){
                if(seg.prod(i,N)>0) break;

                int right=seg.max_right<check>(i);

                if(right==N) break;

                seg.apply(right+1,N,-1);
                seg.apply(right,right+1,ll(1e8));
                cnt.add(right,1);

                //cout<<i<<" "<<right<<endl;
            }
        }

        while(id<si(S)&&S[id].l==i){
            ans[S[id].id]=cnt.sum(S[id].l,S[id].r);
            id++;
        }
    }

    for(int i=0;i<Q;i++){
        cout<<ans[i]<<"\n";
    }

    for(int i=N-1;i>=0;i--){
        if(B[i].fi==0){
            seg.apply(i+1,N,-1);
            seg.apply(i,i+1,1e8);
            cnt.add(i,1);

            while(1){
                if(seg.prod(i,N)>0) break;

                int right=seg.max_right<check>(i);

                if(right==N) break;

                seg.apply(right+1,N,-1);
                seg.apply(right,right+1,ll(1e8));
                cnt.add(right,1);

                //cout<<i<<" "<<right<<endl;
            }
        }

        while(id<si(S)&&S[id].l==i){
            ans[S[id].id]=cnt.sum(S[id].l,S[id].r);
            id++;
        }
    }

    for(int i=0;i<Q;i++){
        cout<<ans[i]<<"\n";
    }
}

