struct unionfind{
    vector<int> par;
    vector<int> size;
    unionfind(const int n):par(n,-1) , size(n,1){}
    int find(const int x){
        if(par[x]==-1)return x;
        return par[x]=find(par[x]);
    }
    void unite(int x,int y){
        x=find(x),y=find(y);
        if(x==y)return;
        if(size[x]>size[y])swap(x,y);
        par[x]=y;
        if(size[x]==size[y])size[y]++;
        return;
    }
};

