struct dsu {
    vector<int> g;
    dsu(int n) : g(n, -1) {}
    int find(int u) {
        return g[u] < 0 ? u : g[u] = find(g[u]);
    }
    bool unite(int u, int v) {
        u = find(u), v = find(v);
        if (u == v) return false;
        if (g[u] > g[v]) swap(u, v);
        g[u] += g[v];
        g[v] = u;
        return true;
    }
    bool same(int u, int v) {
        return find(u) == find(v);
    }
};

