using namespace std;

int find(int X,vector<int> &P){
  if(P.at(X)<0){
    return X;
  }
  return P.at(X)=find(P.at(X),P);
}

void unite(int X,int Y,vector<int> &P){
  X=find(X,P);
  Y=find(Y,P);
  if(X==Y){
    return;
  }
  P.at(Y)+=P.at(X);
  P.at(X)=Y;
}

