const int MAX = 2E5+5;
int link[MAX], size[MAX];

int find(int a){
	if (link[a] == a)
		return a;
	else{
		link[a] = find(link[a]);
		return link[a];
	}
}

void unite(int a, int b){
	a = find(a);
	b = find(b);
	if (a == b) return;
	if (size[a] < size[b]) swap(a,b);
	size[a] += size[b];
	link[b] = a;
}

