	vector<int>mx_c, mn_c;
	T mn = numeric_limits<T>::min(), mx = numeric_limits<T>::max();

public:
	SegtreeBeats() {}
	SegtreeBeats(vector<T>v) { build(v); }
	void build(vector<T>v) {
		n = v.size(), rr = 1;
		while (rr < n) rr *= 2;

		mx_v.assign(2 * rr - 1, mn); mn_v.assign(2 * rr - 1, mx);
		smx_v.assign(2 * rr - 1, mn); smn_v.assign(2 * rr - 1, mx);
		mx_c.assign(2 * rr - 1, 0); mn_c.assign(2 * rr - 1, 0);
		sigm.assign(2 * rr - 1, 0);
		lz_ad.assign(2 * rr - 1, 0);

		for (int i = rr - 1; i < 2 * rr - 1; i++) {
			if (i < rr - 1 + n) {
				mx_v[i] = mn_v[i] = sigm[i] = v[i - rr + 1];
				mn_c[i] = mx_c[i] = 1;
			}
		}
		for (int i = rr - 2; i >= 0; i--) proc(i);
	}
	void chmin(int a, int b, T x) {
		chmin(0, a, b, 0, rr, x);
	}
	void chmax(int a, int b, T x) {
		chmax(0, a, b, 0, rr, x);
	}
	void change(int a, T x) {
		change(0, a, a + 1, 0, rr, x);
	}
	void add(int a, int b, T x) {
		add(0, a, b, 0, rr, x);
	}
	T sum(int a, int b) {
		return sum(0, a, b, 0, rr);
	}
	T rangemax(int a, int b) {
		return rangemax(0, a, b, 0, rr);
	}
	T rangemin(int a, int b) {
		return rangemin(0, a, b, 0, rr);
	}

private:
	void eval(int i) {
		if (i < rr - 1) {
			if (mx_v[i] < mx_v[2 * i + 1]) update_node_max(2 * i + 1, mx_v[i]);
			if (mn_v[i] > mn_v[2 * i + 1]) update_node_min(2 * i + 1, mn_v[i]);

			if (mx_v[i] < mx_v[2 * i + 2]) update_node_max(2 * i + 2, mx_v[i]);
			if (mn_v[i] > mn_v[2 * i + 2]) update_node_min(2 * i + 2, mn_v[i]);
		}
	}
	void proc(int i) {
		sigm[i] = sigm[i * 2 + 1] + sigm[i * 2 + 2];

		if (mx_v[i * 2 + 1] < mx_v[i * 2 + 2]) {
			mx_v[i] = mx_v[i * 2 + 2];
			mx_c[i] = mx_c[i * 2 + 2];
			smx_v[i] = max(smx_v[i * 2 + 2], mx_v[2 * i + 1]);
		}
		else if (mx_v[i * 2 + 1] > mx_v[i * 2 + 2]) {
			mx_v[i] = mx_v[i * 2 + 1];
			mx_c[i] = mx_c[i * 2 + 1];
			smx_v[i] = max(smx_v[i * 2 + 1], mx_v[2 * i + 2]);
		}
		else {
			mx_v[i] = mx_v[i * 2 + 1];
			mx_c[i] = mx_c[i * 2 + 1] + mx_c[i * 2 + 2];
			smx_v[i] = max(smx_v[i * 2 + 1], smx_v[i * 2 + 2]);
		}


		if (mn_v[i * 2 + 1] > mn_v[i * 2 + 2]) {
			mn_v[i] = mn_v[i * 2 + 2];
			mn_c[i] = mn_c[i * 2 + 2];
			smn_v[i] = min(smn_v[i * 2 + 2], mn_v[2 * i + 1]);
		}
		else if (mn_v[i * 2 + 1] < mn_v[i * 2 + 2]) {
			mn_v[i] = mn_v[i * 2 + 1];
			mn_c[i] = mn_c[i * 2 + 1];
			smn_v[i] = min(smn_v[i * 2 + 1], mn_v[2 * i + 2]);
