			mn_v[i] = mn_v[i * 2 + 1];
			mn_c[i] = mn_c[i * 2 + 1] + mn_c[i * 2 + 2];
			smn_v[i] = min(smn_v[i * 2 + 1], smn_v[i * 2 + 2]);
		}
	}
	//change maximam by chmin
	void update_node_max(int i, T x) {
		sigm[i] += (x - mx_v[i]) * mx_c[i];

		if (mx_v[i] == mn_v[i]) mx_v[i] = mn_v[i] = x;
		else if (mx_v[i] == smn_v[i]) mx_v[i] = smn_v[i] = x;
		else mx_v[i] = x;
	}
	void update_node_min(int i, T x) {
		sigm[i] += (x - mn_v[i]) * mn_c[i];

		if (mn_v[i] == mx_v[i]) mn_v[i] = mx_v[i] = x;
		else if (mn_v[i] == smx_v[i]) mn_v[i] = smx_v[i] = x;
		else mn_v[i] = x;
	}
	void update_node_add(int i, int l, int r) {
		if (r - l > 1) {
			lz_ad[i * 2 + 1] += lz_ad[i];
			lz_ad[i * 2 + 2] += lz_ad[i];
		}
		mx_v[i] += lz_ad[i];
		mn_v[i] += lz_ad[i];
		smx_v[i] += lz_ad[i];
		smn_v[i] += lz_ad[i];
		sigm[i] += (min(r, n) - l) * lz_ad[i];
		lz_ad[i] = 0;
	}

	void chmin(int i, int a, int b, int l, int r, T x) {
		if (b <= l || r <= a || mx_v[i] <= x) return;
		eval(i);
		update_node_add(i, l, r);
		if (a <= l && r <= b && smx_v[i] < x) {
			update_node_max(i, x); return;
		}

		chmin(i * 2 + 1, a, b, l, (l + r) / 2, x);
		chmin(i * 2 + 2, a, b, (l + r) / 2, r, x);
		proc(i);
	}
	void chmax(int i, int a, int b, int l, int r, T x) {
		eval(i);
		update_node_add(i, l, r);
		if (b <= l || r <= a || mn_v[i] >= x) return;
		if (a <= l && r <= b && smn_v[i] > x) {
			update_node_min(i, x); return;
		}

		chmax(i * 2 + 1, a, b, l, (l + r) / 2, x);
		chmax(i * 2 + 2, a, b, (l + r) / 2, r, x);
		proc(i);
	}
	void change(int i, int a, int b, int l, int r, T x) {
		if (b <= l || r <= a) return;
		eval(i);
		update_node_add(i, l, r);
		if (a <= l && r <= b) {
			update_node_max(i, x);
			update_node_min(i, x);
			return;
		}
		change(i * 2 + 1, a, b, l, (l + r) / 2, x);
		change(i * 2 + 2, a, b, (l + r) / 2, r, x);
		proc(i);
	}
	void add(int i, int a, int b, int l, int r, T x) {
		if (b <= l || r <= a) return;
		eval(i);
		if (a <= l && r <= b) {
			lz_ad[i] += x;
			update_node_add(i, l, r);
			return;
		}
		update_node_add(i, l, r);
		add(i * 2 + 1, a, b, l, (l + r) / 2, x);
		add(i * 2 + 2, a, b, (l + r) / 2, r, x);
		proc(i);
	}
	T sum(int i, int a, int b, int l, int r) {
		if (b <= l || r <= a) return 0;
		eval(i);
		update_node_add(i, l, r);
		if (a <= l && r <= b) return sigm[i];

		T lv = sum(i * 2 + 1, a, b, l, (l + r) / 2);
		T rv = sum(i * 2 + 2, a, b, (l + r) / 2, r);
		return lv + rv;
	}
	T rangemin(int i, int a, int b, int l, int r) {
		if (b <= l || r <= a) return mx;
		eval(i);
		update_node_add(i, l, r);
		if (a <= l && r <= b) return mn_v[i];

		T lv = rangemin(i * 2 + 1, a, b, l, (l + r) / 2);
		T rv = rangemin(i * 2 + 2, a, b, (l + r) / 2, r);
		return min(lv, rv);
	}
	T rangemax(int i, int a, int b, int l, int r) {
		if (b <= l || r <= a) return mn;
		eval(i);
		update_node_add(i, l, r);
		if (a <= l && r <= b) return mx_v[i];

		T lv = rangemax(i * 2 + 1, a, b, l, (l + r) / 2);
		T rv = rangemax(i * 2 + 2, a, b, (l + r) / 2, r);
		return max(lv, rv);
	}
};

