void join(int x, int y, int st) {
    x = p[x], y = p[y];
    if (x == y) return;
    if (v[x].size() < v[y].size())
        swap(x, y);

    // v[x] > v[y]

    int col_shift = col[x]+st+3-col[y];

    int src = p[y];
    for (int i = 0; i < v[src].size(); i++) {
        int q = v[src][i];
        p[q] = p[x];
        v[p[x]].pb(q);
        (col[q] += col_shift) %= 3;
    }
    v[src].clear();
}

int work(int go) {
    for (int i = 0; i < n; i++) {
        p[i] = i;
        v[i].clear();
        v[i].pb(i);
        col[i] = 0;
    }

    for (int i = 0; i < m; i++) {
        int u, v, st;
        u = games[i].fi.fi;
        v = games[i].fi.se;
        st = games[i].se;

        if (u == go or v == go)
            continue;

        if (p[u] != p[v]) {
            join(u, v, st);
        }
        else {
            if ((col[u]+st)%3 != col[v])
                return i;
        }
    }

    return -1;
}

