void solve(long long N, long long Q, std::vector<long long> t,
           std::vector<long long> u, std::vector<long long> v) {
  atcoder::dsu uf(N);
  REP(i,Q) {
    if (t[i]) cout << (uf.same(u[i], v[i]) ? 1 : 0) << endl;
    else uf.merge(u[i], v[i]);
  }
}

