bool prime(int x) {
    if (!x || x == 1) {
        return false;
    }
    if (x == 2) {
        return true;
    }
    if (!(x & 1)) {
        return false;
    }
    for (int i = 3; i * i <= x; i += 2) {
        if (!(x % i)) {
            return false;
        }
    }
    return true;
}

