class UnionFind {
  vector<int> parent;

public:
  UnionFind(int n) : parent(n, -1) {}

  int root(int n) {
    return parent.at(n) < 0 ? n : parent.at(n) = root(parent.at(n));
  }

  int size(int n) {
    return -1 * parent.at(root(n));
  }

  bool same(int a, int b) {
    return root(a) == root(b);
  }

  void unite(int a, int b) {
    if (!same(a, b)) {
      if (size(a) < size(b)) swap(a, b);
      int ra = root(a);
      int rb = root(b);
      parent.at(ra) += parent.at(rb);
      parent.at(rb) = ra;
    }
  }
};

int main()
{
