    UnionFind(int n) {
        par.resize(n);
        size.resize(n,1);
        rep(i, n) par[i]=i;
    }
    bool same(int x,int y) {
        return find(x)==find(y);
    }
    int consize(int k) {
        return size[k];
    }
    int find(int k) {
        if(par[k]==k) return k;
        return find(par[k]);
    }
    bool unite(int x,int y) {
        if(same(x,y)) return false;
        if(consize(x)<consize(y)) {
            par[x]=par[y];
            size[y]+=size[x];
            size[x]=size[y];
        }
        else {
            par[y]=par[x];
            size[x]+=size[y];
            size[y]=size[x];
        }
        return true;
    }
};
