class DSU{
public:

	vector<int> v;

	DSU(int n){
		v.resize(n);
		for (int i = 0; i < n; i++){
			v[i] = i;
		}
	}

	int _get(int a){
		return v[a] = (v[a] == a ? a : _get(v[a]));
	}

	void _add(int a, int b){
		int x = _get(a), y = _get(b);
		if (x == y) return ;
		v[b] = a;
	}

