    const int intm = 1e9;
    vector<int> shortest(n, intm);
    shortest[s] = 0;
    vector<int> search = {s};
    vector<int> new_search;
    while (!search.empty()) {
        for (auto i : search) {
            for (auto j : connect[i]) {
                if (shortest[j] > 1 + shortest[i]) {
                    shortest[j] = 1 + shortest[i];
                    new_search.emplace_back(j);
