class DSU{
	public:
	 vector<int> siz, par;


	 DSU(int n){
	 	this -> siz.resize(n, 1);
	 	this -> par.resize(n);
	 	for (int i = 0; i < n; i++){
	 		this -> par[i] = i;
	 	}
	 }


	 void _union(int a, int b){
	 	int pa = this -> _get(a),
	 		pb = this -> _get(b);
 		if (pa == pb) return ;
 		if (siz[pa] > siz[pb]){
 			siz[pa] += siz[pb];
 			par[pb] = pa;
 		} else {
 			siz[pb] += siz[pa];
 			par[pa] = pb;
 		}

	 }

	 int _get(int ell){

	 	return this -> par[ell] = (this -> par[ell] == ell ? ell : this -> _get(this -> par[ell])); 
	 }


	 bool _chech(int a, int b){
	 	return this -> _get(a) == this -> _get(b);
	 }
};


