			printf("%d\n", ufs(u) == ufs(v));
		else {
			if (siz[ufs(u)] < siz[ufs(v)])
				swap(u, v);
			siz[ufs(u)] += siz[ufs(v)],
				fa[ufs(v)] = ufs(u);
		}
	}
	return 0;
}

int ufs(const int &u) {
	return fa[u] == fa[fa[u]] ? fa[u] : fa[u] = ufs(fa[u]);
}

