struct uf {
	vector<int> rt, sz;

	uf(int n) {
		rt.resize(n);
		sz.resize(n);
		for (int i = 0; i < n; i++) {
			rt[i] = i;
			sz[i] = 1;
		}
}

	int id(int x) {
		if (rt[x] == x) return x;
		return rt[x] = id(rt[x]);
	}

	bool join(int x, int y) {
		x = id(x);
		y = id(y);
		if (x == y) return false;
		rt[x] = rt[y];
		sz[y] += sz[x];
		sz[x] = 0;
		return true;
	}
};




