struct fast_output{
  #if local
    static constexpr int output_max = 1e2;
  #else
    static constexpr int output_max = 1e7;
  #endif
  char buf[output_max];
  char* itr;
  fast_output(){itr=buf;}
  ~fast_output(){fwrite(buf,1,itr-buf,stdout);}
  void newl(){*itr++='\n';}
  void putc(char c){*itr++=c;}
  void putstr(const char* cs){while(*cs!='\0')*itr++=*cs++;}
  void putstr(std::string const& s){for(char const& c:s)*itr++=c;}
  void putstrln(const char* cs){while(*cs!='\0')*itr++=*cs++;*itr++='\n';}
  void putstrln(std::string const& s){for(char const& c:s)*itr++=c;*itr++='\n';}
  void operator()(uint32_t num){
    if(num==0){*itr++='0';return;}
    char tmp[33];
    int i{};
    while(num){
      tmp[i++] = num%10+'0';
      num /=10;
    }
    while(i--)*itr++=tmp[i];
  }
  void newl(uint32_t num){
    this->operator()(num);
    *itr++='\n';
  }
}out;

