struct dsu {
  dsu(int n = 0) : _cc(n), dat(n, -1) {}

  int root(int v) {
    assert(0 <= v), assert(v < size());
    return dat[v] < 0 ? v : dat[v] = root(dat[v]);
  }
  bool unite(int u, int v) {
    assert(0 <= u), assert(u < size());
    assert(0 <= v), assert(v < size());
    u = root(u), v = root(v);
    if (u == v) return false;
    --_cc;
    if (-dat[u] < -dat[v]) std::swap(u, v);
    dat[u] += dat[v];
    dat[v] = u;
    return true;
  }
  bool same(int u, int v) {
    assert(0 <= u), assert(u < size());
    assert(0 <= v), assert(v < size());
    return root(u) == root(v);
  }
  int size(int v) {
    assert(0 <= v), assert(v < size());
    return -dat[root(v)];
  }
  int size() const { return std::size(dat); }
  int cc() const { return _cc; }

 private:
  int _cc;
  std::vector<int> dat;
};

int main() {
  using namespace std;
  int n = getint(), q = getint();
  dsu d(n);
  while (q--) {
    int t = getint(), u = getint(), v = getint();
    if (t == 0)
      d.unite(u, v);
    else
      putint<int>(d.same(u, v));
  }
}

