void join(int x, int y, int st) {
    x = p[x], y = p[y];
    if (x == y) return;
    if (v[x].size() < v[y].size())
        swap(x, y);
    while (v[y].size()) {
        int q = v[y].back();
        v[x].pb(q);
        p[q] = x;
        v[y].pop_back();
    }
}

int work(int go) {
    for (int i = 0; i < n; i++) {
        p[i] = i;
        v[i].clear();
        v[i].pb(i);
        col[i] = 0;
    }

    for (int i = 0; i < m; i++) {
        int u, v, st;
