        swap(M[i+1].first,M[r].first);
        swap(M[i+1].second,M[r].second);
    }
    return i+1;
};
void q_sort(int p,int r) {
    if (p<r) {
        int q=par(p,r);
        q_sort(p,q-1);
        q_sort(q+1,r);
    }
};
