void union(int a, int b, vector <int> &parent, vector <int> &size)
{
  	int p1 = find_parent(a);
  	int p2 = find_parent(b);
  	if (size[p2] > size[p1])
    {
      	size[p2]+=size[p1];
      	parent[p1]=p2;
    }
  	else
    {
      	size[p1]+=size[p2];
      	parent[p2]=p1;
    }
}

int find_parent(int a, vector <int> &parent)
{
  	if (parent[a]==a) return a;
  	return parent[a]=find_parent(parent[a], parent);
}

int main()
{
	int N,Q;
  	cin >> N >> Q;
  	vector <int> parent(N), size(N,1);
  	for (int i=0; i<N; ++i) parent[i]=i;
  	while (Q--)
    {
      	int type, node1, node2;
      	cin >> type >> node1 >> node2;
      	if (type==0) union(node1, node2, parent,size);
      	else cout << (find_parent(node1, parent) == find_parent(node2,parent)) << "\n";
    }
}

#include <bits/stdc++.h>
using namespace std;
const int maxN = 2e5 + 5;

int par[maxN], siz[maxN];

void init() {
	for (int i = 0; i < maxN; ++i) {
    	par[i] = i, siz[i] = 1; 
    }
}

int find(int x) {
	return par[x] == x ? x : par[x] = find(par[x]); 
}

bool same(int x, int y) {
	return find(x) == find(y);  
}

void unify(int x, int y) {
	x = find(x), y = find(y);
  	if (x == y) return;
  	if (siz[x] > siz[y]) {
    	siz[x] += siz[y];
      	par[y] = x;
    }
  	else {
    	siz[y] += siz[x];
      	par[x] = y;
    }
}

int main() {
	int n, q;
  	cin >> n >> q;
  	init();
  	for (int i = 0; i < q; ++i) {
    	int type, u, v;
      	cin >> type >> u >> v;
      	if (type) {
         	cout << same(u, v) << '\n';          
        }
      	else {
 			unify(u, v);
        }
    }
  	return 0;
}

