using namespace std;
using ll = long long;

class UnionFind{
  private:
	vector<int> data;

  public:
	UnionFind(int n) : data(n,-1) {}
	int root(int i) { return data[i] < 0 ? i : data[i] = root(data[i]); }
	int size(int i) { return -data[root(i)]; }
	bool same(int x, int y) {return root(x) == root(y); }
	bool connected() {return size(0) == (int)data.size(); }

	bool unit(int i,int j){
		i = root(i);
		j = root(j);
		if(i != j){
			data[i] += data[j];
			data[j] = i;
		}
		return i != j;
	}
};

int main()
{
	int n, q; cin >> n >> q;
	UnionFind tree(n);
	for(int i = 0; i < q; i++) {
		int a, b, c; cin >> a >> b >> c;
		if(a) {
			cout << tree.same(b, c) << endl;
		} else {
			tree.unit(b, c);
		}
	}
}

