struct union_find
{
    vector<int> par;  //親の番号　
    vector<int> rank; //木の深さ(根のランクは0)
    vector<int> siz;  //要素xが根なら木の頂点数を格納する
    //初期化子リストを用いた初期化
    union_find(int N) : par(N), rank(N), siz(N)
    {
        for (int i = 0; i < N; i++)
        {
            par[i] = i;
            rank[i] = 0;
            siz[i] = 1;
        }
    }
    //要素xが所属する木の根を再帰的に発見する
    int root(int x)
    {
        if (par[x] == x)
            return x;
        return par[x] = root(par[x]); //経路圧縮
    }
    //要素xが属する木と要素yが属する木の併合
    void unite(int x, int y)
    {
        int rx = root(x);
        int ry = root(y);
        if (rx == ry)
            return; //同じ木に属してたらそのまま
        if (rank[rx] < rank[ry])
        {
            par[rx] = ry; //根がryの木に併合
            siz[ry] = siz[rx] + siz[ry];
        }
        else
        {
            par[ry] = rx; //根がrxの木に併合
            siz[rx] = siz[rx] + siz[ry];
            if (rank[rx] == rank[ry])
                rank[rx]++;
        }
    }
    //要素xが属する木と要素yが属する木が同じならtrueを返す
    bool same(int x, int y)
    {
        return root(x) == root(y);
    }
    //要素xが属する木の頂点数を返す
    int size(int x)
    {
        return siz[root(x)];
    }
};
int main()
{
    FastIO io;
    int N, Q;
    io.read(N);
    io.read(Q);
    union_find tree(N);
    for (int i = 0; i < Q; i++)
    {
        int a, b, c;
        io.read(a);
        io.read(b);
        io.read(c);
        if (a==1)
            if (tree.same(b,c))
                io.write(1);
            else
                io.write(0);
        if (a==0)
            tree.unite(b,c);
    }
    return 0;
}

