template<class T = int>
struct UnionFind{
    vector<T> par;
    vector<T> ran;
    vector<T> siz;
    T tree_num;

    UnionFind(T n) : par(n),ran(n,0),siz(n,1),tree_num(n){
        rep(i,n){
            par[i] = i;
        }
    }
    T find(T x){
        if(x == par[x])return x;
        else return par[x] = find(par[x]);
    }
    void unite(T x,T y){
        x = find(x);
        y = find(y);
        if(x == y)return;
        tree_num--;
        if(ran[x] < ran[y]){
            siz[y] += siz[x];
            par[x] = y;
        }
        else{
            siz[x] += siz[y];
            par[y] = x;
            if(ran[x] == ran[y])ran[x]++;
        }
    }
    bool same(T x,T y){
        return find(x) == find(y);
    }
    T get_size(T x){
        return siz[find(x)];
    }
    T renketsu_seibun(){
        return tree_num;
    }
};

