//Modifiable-DSU
//Using path compression and union by size

vector<ll> parent(N);
vector<ll> SS(N);
void initialize(ll node)
{
	parent.at(node) = node;
	SS.at(node) = 1;
}
ll find_parent(ll node)
{
	if(parent.at(node) == node) return node;
	return parent.at(node) = find_parent(parent.at(node));
}
void merge_set(ll a, ll b)
{
	a = find_parent(a);
	b = find_parent(b);

	if(a != b)
	{
		if(SS.at(a) < SS.at(b))
			swap(a,b);
		parent.at(b) = a;
		SS.at(a) += SS.at(b);
	}
}

