struct UnionF {
    vector<ll> S;

    UnionF(ll a){
        S=vector<ll>(a);
        for(ll i=0;i<a;i++)S[i]=i;
    }

    ll FFi(ll i){
        if(S[i]==i)return i;
        S[i]=FFi(S[i]);
        return S[i];
    }

    void marge(ll a,ll b){
        ll aa=FFi(a),bb=FFi(b);
        if(aa==bb)return;
        ll mms = (aa<bb)?aa:bb;
        S[aa]=mms;S[bb]=mms;
    }

    bool equalU(ll a,ll b){return (FFi(S[a])==FFi(S[b]));}

};

