using namespace std;

class Edge
{
    public:
    int src,dest;
};
class Graph
{
    public:
    int V,E;
    Edge* edge;
};

Graph* createGraph(int V,int E)
{
    Graph* graph=new Graph();
    graph->V=V;
    graph->E=E;
    graph->edge = new Edge[graph->E * sizeof(Edge)];
    return graph;
}
int find(int parent[], int i)
{
    if(parent[i]==-1)
        return i;
    return find(parent,parent[i]);
} 
int Union(int parent[],int x,int y)
{
    int xset=find(parent,x);
    int yset=find(parent,y);
    if(xset!=yset)
    {
        parent[xset]=yset;
    }
}
int isPath(Graph* graph,int parent[],int u,int v)
{
    int x=find(parent,u);
    int y=find(parent,v);
    if(x==y)
    {
        return 1;
    }
    return 0;
}
int main()
{
    int V,Q;
    cin>>V>>Q;
    Graph* graph=createGraph(V,0);
    int* parent =new int[graph->V*sizeof(int)];
    memset(parent,-1,sizeof(int)*graph->V);
    for (int i=0;i<Q;i++)
    {
        int action,u,v;
        cin>>action>>u>>v;
        if(action==0)
        {
            graph->edge[graph->E].src=u;
            graph->edge[graph->E].dest=v;
            graph->E+=1;
            Union(parent,u,v);
        }
        else
        {
            cout<<isPath(graph,parent,u,v)<<endl;
        }

    }
}

