	for(int i = 0; i < m; i++){
		cin >>a>>u>>v;
		if (!a){
			ds -> _union(u,v);
		} else {
			if (ds -> _chech(u,v)) {
				cout << 1 << el;
			} else {
				cout << 0 << el;
			}
		}
	}
}

