struct UnionFind {

  VI par, siz;
  int cnt;

  UnionFind() {}

  UnionFind(int n):par(n), siz(n,1),cnt(n) {
    iota(ALL(par),0);
  }

  void init(int n) {
    par.assign(n,0);
    siz.assign(n,1);
    iota(ALL(par),0);
    cnt = n;
  }

  int find(int x) {
    if(par[x] == x){
      return x;
    }else{
      return par[x] = find(par[x]);
    }
  }

  bool unite(int x, int y){
    x = find(x);
    y = find(y);
    if(x == y) return false;
    cnt--;

    if(siz[x] < siz[y]){
      swap(x,y);
    }
    siz[x] += siz[y];
    par[y] = x;
    return true;
    }

  bool same(int x, int y){
    return find(x) == find(y);
  }

  int size(int x){
    return siz[find(x)];
  }
};

