#include <bits/stdc++.h>
using namespace std;

vector<int> par;
vector<int> RA;

void Re(int a){
  par.resize(a);
  RA.resize(a);
  for(int i=0;i<a;i++){
    par[i]=i;
  }
}
int root(int a){
  if(a==par[a]){
    return a;
  }
  else{
    return par[a]=root(par[a]);
  }
}
void UN(int a,int b){
  a=root(a);
  b=root(b);
  if(a==b){
    return;
  }
  else if(RA[a]<RA[b]){
    par[a]=b;
  }
  else{
    par[b]=a;
  }
  if(RA[a]==RA[b]){
    RA[a]++;
  }
}
int same(int a,int b){
  if(root(a)==root(b)){
    return 1;
  }
  else{
    return 0;
  }
}

int main() {
  int N,Q;
  cin>>N>>Q;
  Re(N);
  for(int i=0;i<Q;i++){
    int a,b,c;
    cin>>a>>b>>c;
    if(a){
      cout<<same(b,c)<<endl;
    }
    else{
      UN(b,c);
    }
  }
}

