const ll max_n = 1e6+5;
ll ufpar[max_n], ufrank[max_n], ufnum[max_n];
//初期化忘れるな！
void init(ll n){
	rep(ii,0,n){
		ufpar[ii] = ii;
		ufrank[ii] = 0;
		ufnum[ii] = 1;
	}
}
ll ufind(ll x){
	if(ufpar[x] == x) {
		return x;
	} else {
		ll umm = ufind(ufpar[x]);
		return ufpar[x] = umm;
	}
}
bool unite(ll x, ll y){
	x = ufind(x);
	y = ufind(y);
	if(x == y) return false;
	if(ufrank[x] < ufrank[y]) swap(x,y);
	if(ufrank[x] == ufrank[y]) ufrank[y]++;
	ufpar[y] = x;
	ufnum[x] += ufnum[y];
	ufnum[y] = 0;
	return true;
}
//xとyが同じ連結成分か
bool usame(ll x, ll y){
	return ufind(x) == ufind(y);
}
//xを含む連結成分のサイズ
ll usz(ll x){
	return ufnum[ufind(x)];
}

