    int N,Q; cin >> N >> Q;
    UnionFind uf(N);
    rep(i,Q) {
        int t,a,b; cin >> t >> a >> b;
        if (t == 0) {
            uf.unite(a,b);
        } else {
            if (uf.same(a,b)) cout << 1 << '\n';
            else cout << 0 << '\n';
        }
    }
    return 0;
}

