class unionfind {
  vector<int> par, s;

public:
  unionfind(int n) {
    for (int i = 0; i < n; i++) {
      par.push_back(i);
      s.push_back(1);
    }
  }

  int find(int n) {
    if (par.at(n) == n) return n;
    return par.at(n) = find(par.at(n));
  }

  void merge(int m, int n) {
    m = find(m);
    n = find(n);
    if (s.at(m) > s.at(n)) swap(m, n);
    par.at(m) = n;
    s.at(n) += s.at(m);
  }
};

int main() {
