 struct UF {
	vector<int>par;//親
	vector<int>sz;//要素数

  UF(int n){
    sz.resize(n,1);
    par.resize(n);
    for(int i=0;i<n;++i){
      par[i]=i;
    }
  }

	//木の根を求める
	int find(int x) {
		if (par[x] == x) {
			return x;
		}
		else {
			return par[x] = find(par[x]);//経路圧縮
		}
	}

	//xとyの属する集合を併合
	bool unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (x == y)return false;//すでに同じ集合に属している

		if (sz[x] < sz[y]) {//要素数が小さい方を下に
			par[x] = y;
      sz[y]+=sz[x];
		}
		else {
			par[y] = x;
			sz[x]+=sz[y];
		}
		return true;
	}

	//xとyが同じ集合に属するかを判定
	bool same(int x, int y) {
		return find(x) == find(y);
	}

    int size(int k){//要素数を求める
        return sz[find(k)];
    }
};


