					AddEdge(i * M + j, i * M + j + 1, 1, 1);
				if (i > 0 && a[i - 1][j] == '.')
					AddEdge(i * M + j, (i - 1) * M + j, 1, 2);
				if (j > 0 && a[i][j - 1] == '.')
					AddEdge(i * M + j, i * M + j - 1, 1, 3);
			}
	for (int i = 0; i < N; ++i)
		for (int j = 0; j < M; ++j)
			if (a[i][j] == '.')
				if (i + j & 1)
