void AddEdge(const int &from, const int &to, const int &cap, const char &flag) {
	ge[m] = edge(to, cap, flag);
	gl[from].push_back(m++);
	ge[m] = edge(from, 0, -1);
	gl[to].push_back(m++);
}

int MaxFlow(const int &from, const int &to) {
	int flow = 0;
	while (true) {
		memset(depth, -1, sizeof(depth));
		depth[from] = 0;
		int h = 0, t = 1; q[h] = from;
		while (h < t) {
			int u = q[h++];
			for (int i = 0; i < gl[u].size(); ++i) {
				edge &e = ge[gl[u][i]];
				if (e.cap > 0 && depth[e.to] == -1)
					q[t++] = e.to, depth[e.to] = depth[u] + 1;
			}
		}
		if (depth[to] == -1)
			return flow;

		memset(iter, 0, sizeof(iter));
		int f;
		while (f = dfs(from, to, inf))
			flow += f;
	}
}

int dfs(const int &from, const int &to, const int &flow) {
	if (from == to)
		return flow;
	for (int &i = iter[from]; i < gl[from].size(); ++i) {
		edge &e = ge[gl[from][i]], &e1 = ge[gl[from][i] ^ 1];
		if (e.cap > 0 && depth[e.to] == depth[from] + 1) {
			int f = dfs(e.to, to, min(flow, e.cap));
			if (f) {
				e.cap -= f;
				e1.cap += f;
				return f;
			}
		}
	}
	return 0;
}

