  int n,q;
  cin>>n>>q;

  UF uf(n);

  rep(i,q){
    int t,u,v;
    cin>>t>>u>>v;
    if(t==0) uf.unite(u,v);
    if(t==1) cout << uf.same(u,v) << endl;
