class DSU {
private:
    vector<ll> parent;
    vector<ll> size;
public:
    explicit DSU(ll n) {
        parent = vector<ll>(n);
        size = vector<ll>(n, 1);
        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }
    }

    ll findSet(ll node) {
        if (node == parent[node]) {
            return node;
        }
        parent[node] = findSet(parent[node]);
        return parent[node];
    }

    bool isSameSet(ll node1, ll node2) {
        return (findSet(node1) == findSet(node2));
    }

    void unionSets(ll node1, ll node2) {
        node1 = findSet(node1);
        node2 = findSet(node2);
        if (node1 != node2) {
            if (size[node1] < size[node2]) {
                swap(node1, node2);
            }
            parent[node2] = node1;
            size[node1] += size[node2];
        }
    }

};

