{
    vector<int> par, rank;

    UnionFind(int n){
        par.resize(n);
        rank.resize(n);
        for(int i = 0; i < n; i++){
            par[i] = i;
            rank[i] = 0;
        }
    }

    int find(int i){
        if(i == par[i]) return i;
        return par[i] = find(par[i]);
    }

