class UF(size:Int) {
	private val a = IntArray(size) {-1}

	fun root(t:Int):Int = if(a[t]<0) t else root(a[t]).also {a[t] = it}

	fun isConnected(a:Int,b:Int) = root(a)==root(b)
	fun groupSize(t:Int) = -a[root(t)]

	fun connect(p:Int,q:Int):Boolean {
		val r = root(p)
		val s = root(q)
		if(r==s) return false
		if(a[r]>a[s]) {
			a[s] += a[r]
			a[r] = s
		} else {
			a[r] += a[s]
			a[s] = r
		}
