    private static class UF {
        int []par;
        private UF(int n) {
            par = new int[n];
            for(int i=0;i<n;i++) {  
                par[i] = i;
            }
        }
        public boolean same(int i, int j) {
            int ri = root(i); 
            int rj = root(j); 
            return ri == rj;
        }

        public void unite(int i, int j) {
            int ri = root(i);
            int rj = root(j);
            if (ri == rj) return;
            par[ri] = rj;
        }
        public int root(int x) {
            if (par[x] == x) return x;
            return par[x] = root(par[x]);
        }
    }
}

