				Object[] group = new Object[parent.length];
				java.util.ArrayList<java.util.ArrayList<Integer>> ret = new java.util.ArrayList<>();
				for (int i = 0;i < parent.length;++ i) {
					int leader = getLeader(i);
					Object put = group[leader];
					if (put == null) {
