	        for (int i = 0; i < size; i++) {
	            parents[i] = i;
	        }
	    }

	    public int find(int x) {
	        if (x == parents[x]) {
	            return x;
	        } else {
	            return parents[x] = find(parents[x]);
	        }
	    }

	    public boolean same(int x, int y) {
	        return find(x) == find(y);
	    }

	    public void unite(int x, int y) {
	        if (!same(x, y)) {
	            parents[find(x)] = find(y);
	        }
	    }
	}
