namespace AtCoder
{
    class DSU
    {
        public int Count;
        private int[] ParentOrSize;

        /// <summary>
        /// <see cref="DSU"/> クラスの新しいインスタンスを、<paramref name="n"/> 頂点 0 辺の有向グラフとして初期化します。
        /// </summary>
        /// <remarks>
        /// <para>制約: 0≤<paramref name="n"/>≤10^8</para>
        /// <para>計算量: O(<paramref name="n"/>)</para>
        /// </remarks>
        public DSU(int n)
        {
            Count = n;
            ParentOrSize = new int[n];
            for (int i = 0; i < ParentOrSize.Length; i++) ParentOrSize[i] = -1;
        }

        /// <summary>
        /// 頂点 <paramref name="a"/> と頂点 <paramref name="b"/> を結ぶ辺を追加し、それらの代表元を返します。
        /// </summary>
        /// <remarks>
        /// <para>制約: 0≤<paramref name="a"/>, <paramref name="b"/>&lt;n</para>
        /// <para>計算量: ならしO(a(n))</para>
        /// </remarks>
        public int Merge(int a, int b)
        {
            Debug.Assert(0 <= a && a < Count);
            Debug.Assert(0 <= b && b < Count);
            int x = Leader(a), y = Leader(b);
            if (x == y) return x;
            if (-ParentOrSize[x] < ParentOrSize[y]) (x, y) = (y, x);
            ParentOrSize[x] += ParentOrSize[y];
            ParentOrSize[y] = x;
            return x;
        }

        /// <summary>
        /// 頂点 <paramref name="a"/>, <paramref name="b"/> が連結かどうかを返します。
        /// </summary>
        /// <remarks>
        /// <para>制約: 0≤<paramref name="a"/>, <paramref name="b"/>&lt;n</para>
        /// <para>計算量: ならしO(a(n))</para>
        /// </remarks>
        public bool Same(int a, int b)
        {
            Debug.Assert(0 <= a && a < Count);
            Debug.Assert(0 <= b && b < Count);
            return Leader(a) == Leader(b);
        }

        private int[] buffer = new int[1024];
        /// <summary>
        /// 頂点 <paramref name="a"/> の属する連結成分の代表元を返します。
        /// </summary>
        /// <remarks>
        /// <para>制約: 0≤<paramref name="a"/>&lt;n</para>
        /// <para>計算量: ならしO(a(n))</para>
        /// </remarks>
        public int Leader(int a)
        {
            if (ParentOrSize[a] < 0) return a;
            while (0 <= ParentOrSize[ParentOrSize[a]])
            {
                (a, ParentOrSize[a]) = (ParentOrSize[a], ParentOrSize[ParentOrSize[a]]);
            }
            return ParentOrSize[a];
        }


        /// <summary>
        /// 頂点 <paramref name="a"/> の属する連結成分のサイズを返します。
        /// </summary>
        /// <remarks>
        /// <para>制約: 0≤<paramref name="a"/>&lt;n</para>
        /// <para>計算量: ならしO(a(n))</para>
        /// </remarks>
        public int Size(int a)
        {
            Debug.Assert(0 <= a && a < Count);
            return -ParentOrSize[Leader(a)];
        }

        /// <summary>
        /// グラフを連結成分に分け、その情報を返します。
        /// </summary>
        /// <para>計算量: O(n)</para>
        /// <returns>「一つの連結成分の頂点番号のリスト」のリスト。</returns>
        public List<List<int>> Groups()
        {
            throw new NotImplementedException();
        }
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;

namespace AtCoderLibraryCSharp.Examples
{
    public static class Program
    {
        public static void Main()
        {
            var NQ = Console.ReadLine().Split(" ").Select(int.Parse).ToArray();
            var (N, Q) = (NQ[0], NQ[1]);
            var dsu = new DisjointSetUnion(N);
            for (var i = 0; i < Q; i++)
            {
                var TUV = Console.ReadLine().Split(" ").Select(int.Parse).ToArray();
                var (t, u, v) = (TUV[0], TUV[1], TUV[2]);
                if (t == 0) dsu.Merge(u, v);
                else Console.WriteLine(dsu.IsSame(u, v) ? 1 : 0);
            }
        }

        public class DisjointSetUnion
            {
                private readonly int _n;
                private readonly int[] _parentOrSize;

                public DisjointSetUnion(int n = 0)
                {
                    _n = n;
                    _parentOrSize = Enumerable.Repeat(-1, n).ToArray();
                }

                public int Merge(int a, int b)
                {
                    if (a < 0 || _n <= a) throw new IndexOutOfRangeException(nameof(a));
                    if (b < 0 || _n <= b) throw new IndexOutOfRangeException(nameof(b));
                    var (x, y) = (LeaderOf(a), LeaderOf(b));
                    if (x == y) return x;
                    if (-_parentOrSize[x] < -_parentOrSize[y]) (x, y) = (y, x);
                    _parentOrSize[x] += _parentOrSize[y];
                    _parentOrSize[y] = x;
                    return x;
                }

                public bool IsSame(int a, int b)
                {
                    if (a < 0 || _n <= a) throw new IndexOutOfRangeException(nameof(a));
                    if (b < 0 || _n <= b) throw new IndexOutOfRangeException(nameof(b));
                    return LeaderOf(a) == LeaderOf(b);
                }

                public int LeaderOf(int a)
                {
                    if (a < 0 || _n <= a) throw new IndexOutOfRangeException(nameof(a));
                    if (_parentOrSize[a] < 0) return a;
                    return _parentOrSize[a] = LeaderOf(_parentOrSize[a]);
                }

                public int SizeOf(int a)
                {
                    if (a < 0 || _n <= a) throw new IndexOutOfRangeException(nameof(a));
                    return -_parentOrSize[LeaderOf(a)];
                }

                public IEnumerable<IEnumerable<int>> GetGroups()
                {
                    var leaders = new int[_n];
                    var groupSize = new int[_n];
                    for (var i = 0; i < _n; i++)
                    {
                        leaders[i] = LeaderOf(i);
                        groupSize[leaders[i]]++;
                    }

                    var ret = new List<int>[_n].Select(x => new List<int>()).ToArray();
                    for (var i = 0; i < _n; i++) ret[leaders[i]].Add(i);
                    return ret.Where(x => x.Any());
                }
            }
    }
}

