        /// <para>制約: 0≤<paramref name="a"/>&lt;n</para>
        /// <para>計算量: ならしO(a(n))</para>
        /// </remarks>
        public int Leader(int a)
        {
            int ptr = 0;
            while (0 <= ParentOrSize[a])
            {
                buffer[ptr++] = a;
                a = ParentOrSize[a];
            }
            ptr--;
            while (0 <= ptr)
            {
                ParentOrSize[buffer[ptr]] = a;
                ptr--;
            }
            return a;
        }


        /// <summary>
