public class UnionFind
{
    public int GroupCount { get; private set; }
    protected int[] data;
    public virtual int this[int i] => Find(i);
    public UnionFind(int size)
    {
        data = Create(size, () => -1);
        GroupCount = size;
    }
    protected int Find(int i) => data[i] < 0 ? i : (data[i] = Find(data[i]));
    public int Size(int i) => -data[Find(i)];
    public virtual bool Union(int u, int v)
    {
        u = Find(u); v = Find(v);
        if (u == v) return false;
        if (data[u] > data[v]) swap(ref u, ref v);
        GroupCount--;
        data[u] += data[v];
        data[v] = u;
        return true;
    }
}

public class FastScanner
{
    //0x0a:LF 0x20:SPC 0x2d:- 0x30 ~ 0x39: 0 ~ 9
    static System.IO.Stream str = System.Console.OpenStandardInput();
    const int size = 1 << 10;
    static byte[] buffer = new byte[size];
    static int ptr;
    static int len;
    public int Int
    {
        get
        {
            var c = Read();
            while (c < 0x21)
            {
                c = Read();
            }
            var n = false;
            if (c == '-')
            {
                n = true;
                c = Read();
            }
            var ret = 0;
            while (c >= 0x30)
            {
                ret = ret * 10 + (c & 15);
                c = Read();
            }
            return n ? -ret : ret;
        }
    }
    public long Long
    {
        get
        {
            var c = Read();
            while (c < 0x21)
            {
                c = Read();
            }
            var n = false;
            if (c == '-')
            {
                n = true;
                c = Read();
            }
            var ret = 0L;
            while (c >= 0x30)
            {
                ret = ret * 10 + (c & 15);
                c = Read();
            }
            return n ? -ret : ret;
        }
    }
    byte Read()
    {
        if (ptr == len)
        {
            len = str.Read(buffer, 0, size);
            if (len == 0) return 0;
            ptr = 0;
        }
        return buffer[ptr++];
    }
}

