public class UnionFind {
	private long[] data;

	public UnionFind(long size) {
		data = new long[size];
		for (int i = 0; i < size; i++) data[i] = -1;
	}
	public bool Unite(long x, long y) {
		x = Find(x);
		y = Find(y);

		if (x != y) {
			if (data[y] < data[x]) { var t = y; y = x; x = t; }
			data[x] += data[y];
			data[y] = x;
		}
		return x != y;
	}
	public bool IsSameGroup(long x, long y) { return Find(x) == Find(y); }
	public long Find(long x) { return data[x] < 0 ? x : data[x] = Find(data[x]); }
	public long Size(long x) { return -data[Find(x)]; }
	public List<long>[] Groups(){
		Dictionary<long,int> idx = new Dictionary<long, int>();
		int k=0;
		var ret = new List<List<long>>();
		for (int i = 0; i < data.Length; i++) {
			var p = Find(i);
			int j;
			if(!idx.ContainsKey(p)) {
				j = k;
				idx[p] = k++;
				ret.Add(new List<long>());
			}else{
				j = idx[p];
			}
			ret[j].Add(i);
		}
		return ret.ToArray();
	}
}












