{
    class Program
    {
        public static void Solve(Input input)
        {
            var n = input.NextInt();
            var q = input.NextInt();

            var uf = new UnionFind(n);
            for (int i = 0; i < q; i++)
            {
                var query = input.NextInt(3);
                if (query[0] == 0)
                {
                    uf.Merge(query[1], query[2]);
                }
                else
                {
                    if (uf.Same(query[1], query[2]))
                    {
                        Console.WriteLine(1);
                    }
                    else
                    {
                        Console.WriteLine(0);
                    }
                }
            }
        }

        /// <summary>
        /// 重み付きUF木
        /// </summary>
        public class UnionFind
        {
            private readonly int[] _rank;
            private readonly int[] _size;
            private readonly int[] _parentId;
            private readonly int[] _diffWeight;

            /// <summary>
            /// 
            /// </summary>
            /// <param name="size">ノードの総数</param>
            public UnionFind(int size)
            {
                _rank = new int[size];
                _size = Enumerable.Repeat(1, size).ToArray();
                _parentId = Enumerable.Range(0, size).ToArray();
                _diffWeight = new int[size];
            }

            /// <summary>
            /// 同一の親を持つか
            /// </summary>
            /// <param name="x"></param>
            /// <param name="y"></param>
            /// <returns></returns>
            public bool Same(int x, int y)
            {
                return FindRoot(x) == FindRoot(y);
            }

            /// <summary>
            /// 指定ノードのrootを返す
            /// </summary>
            /// <param name="x"></param>
            /// <returns></returns>
            public int FindRoot(int x)
            {
                if (x != _parentId[x])
                {
                    // 経路中のノードのパラメータを更新しておく
                    var root = FindRoot(_parentId[x]);
                    _diffWeight[x] += _diffWeight[_parentId[x]];
                    _parentId[x] = root;
                }

                return _parentId[x];
            }

            /// <summary>
            /// 親経路との重さを返す
            /// </summary>
            /// <param name="x"></param>
            /// <returns></returns>
            public int Weight(int x)
            {
                FindRoot(x);

                return _diffWeight[x];
            }

            /// <summary>
            /// x,yが同一の親を持つ場合、Weightの差分（y-x）を返す
            /// </summary>
            /// <param name="x"></param>
            /// <param name="y"></param>
            /// <returns></returns>
            public int Weight(int x, int y)
            {
                return Weight(y) - Weight(x);
            }

            /// <summary>
            /// 重みをつけて合体する
            /// </summary>
            /// <param name="x"></param>
            /// <param name="y"></param>
            /// <param name="w"></param>
            public void Merge(int x, int y, int w = 0)
            {
                w += Weight(x) - Weight(y);

                x = FindRoot(x);
                y = FindRoot(y);

                if (x == y) return;

                if (_rank[x] < _rank[y])
                {
                    _parentId[x] = y;
                    _size[y] += _size[x];
                    _diffWeight[x] = -w;
                }
                else
                {
                    _parentId[y] = x;
                    _size[x] += _size[y];
                    _diffWeight[y] = w;

                    if (_rank[x] == _rank[y])
                    {
                        _rank[x]++;
                    }
                }
            }

            /// <summary>
            /// xと同じ親を持つノードの数
            /// </summary>
            /// <param name="x"></param>
            /// <returns></returns>
            public int SameCount(int x)
            {
                x = FindRoot(x);

                return _size[x];
            }
        }

        #region Main
        public static void Main(string[] args)
        {
            // 出力が少ないときはこれをセットする方が時間かかるけれど
