class UnionFindTree
    attr_accessor:parent,:size,:rank,:group
    def initialize(n)
        @parent=Array.new(n){|idx| idx}
        @rank=Array.new(n,0)
        @size=Array.new(n,1)
    end

    def find(x)
        return x if @parent[x]==x
        @parent[x]=find(@parent[x])
        return @parent[x]
    end

    def union(x,y)
        par_x=find(x)
        par_y=find(y)
        return if par_x==par_y
        if @rank[par_x]<@rank[par_y]
            @parent[par_x]=par_y
            @size[par_y]+=@size[par_x]
        else
            @parent[par_y]=par_x
            @size[par_x]+=@size[par_y]
            @rank[par_x]+=1 if @rank[par_x]==@rank[par_y]
        end
    end

    def same?(x,y)
        return find(x)==find(y)
    end

    def get_size(x)
        return @size[find(x)]
    end
    def make_groups()
      n=@parent.size
      @group=Array.new(n,[])
      @parent.each_with_index do|child,i|
        @group[i]<< child 
      end
    end
end
