import "fmt"

type UnionFind struct {
	Par map[int]int
}

// NewUnionFind returns *UnionFind
func NewUnionFind(n []int) *UnionFind {
	par := make(map[int]int)
	for i := 0; i < len(n); i++ {
		par[n[i]] = -1
	}
	return &UnionFind{
		Par: par,
	}
}

// Root
func (u *UnionFind) Root(x int) int {
	c := u.Par[x]
	if c < 0 {
		return x
	}
	u.Par[x] = u.Root(u.Par[x])
	return u.Par[x]
}

func (u *UnionFind) Unite(x, y int) bool {
	x = u.Root(x) //xの根をrx
	y = u.Root(y) //yの根をry
	if x == y {
		return false
	} //xとyの根が同じ(=同じ木にある)時はそのまま
	if u.Par[x] > u.Par[y] {
		tmp := x
		x = y
		y = tmp
	}
	u.Par[x] += u.Par[y]
	u.Par[y] = x
	return true
}

func (u *UnionFind) Same(x, y int) bool { // 2つのデータx, yが属する木が同じならtrueを返す
	rx := u.Root(x)
	ry := u.Root(y)

	// fmt.Println("(x, y)", x, y)
	// fmt.Println("(rx, ry)", rx, ry)
	// fmt.Println(u.Par)
	return rx == ry
}

func (u *UnionFind) Size(x int) int {
	n := u.Root(x)
	return -u.Par[n]
}

