ll create1001001(ll num, ll m, ll num_of_1, ll nb = 31){
    // e.g. 1001001001 -> num = 3
    // e.g. 111111 -> num = 1 (REPUNIT)
    // Calculate the modulo m of 100..100...100..1 (the length of each 00... is num - 1. The # of 1 is 2^i.)
    // Then calculate the modulo m of 100...100...100...1 (The # of 1 is num_of_1 using the memo.)
    vl memo(nb, 1); ll v = 0, tot = 1, coef = power_mod(10, num, m);
    rep(j, nb){
        ll c10 = power_mod(coef, 1LL << j, m);
        memo[j + 1] = ((memo[j] * c10) % m + memo[j]) % m;
        if (num_of_1 >> j & 1){
            (v += (memo[j] * tot) % m) %= m;
            (tot *= power_mod(coef, 1LL << j, m)) %= m;
        }
    }
    return v;
}

ll GaussJordanBitVector(vl &bs){
    ll n = bs.size();
    ll rank = 0; ll j = 0;
    revrep(i, N_DIGITS){
        for(j = rank; j < n; j++) if (bs[j] & (1LL << i)) break;
        if (j == n) continue;
        if (j > rank) bs[rank] ^= bs[j];
        for (j = 0; j < n; j++) if (j != rank) bs[j] = min(bs[j], bs[j] ^ bs[rank]);
        rank++;
    }
    return rank;
}

ll GaussJordan(vl2& A, ll mod, bool is_extended = false, bool det = false){
    /*
    Ax = b

    Parameters
    ----------
    A: m x n matrix
        The matrix of interest

    is_extended: bool
        if A includes the term of b (e.g. when solving linear equation), true
        otherwise false.

    Property: The product of diagonal elements of upper triangle matrix is equal to the determinant of this matrix.
    */

    ll rank = 0, m = A.size(), n = A[0].size();
    rep(r, m) rep(c, n) A[r][c] = modf(A[r][c], mod);

    ll pivot, inv, ret = 1; vl tmp;
    if (det) tmp = vl(n);
    rep(c, n){
        if (is_extended && c == n - 1) break;
        pivot = -1;
        For(r, rank, m) if (A[r][c] != 0) {pivot = r; break;}
        if (pivot == -1){
            if (det) return 0;
            continue;
        }

        swap(A[pivot], A[rank]);
        ret = modf(ret * A[rank][c], mod), inv =  modinv(A[rank][c], mod);
        vl& ax = det ? tmp : A[rank];
        rep(c2, n) ax[c2] = A[rank][c2] * inv % mod;

        rep(r, m) if (r != rank && A[r][c]){
            ll base = A[r][c];
            rep(c2, n)
                A[r][c2] = modf(A[r][c2] - ax[c2] * base, mod);
        }
        ++rank;
    }

    return det ? ret : rank;
}

ll linear_equation(vl2 A, vl b, vl &res){
    ll m = A.size(), n = A[0].size();
    vl2 M(m, vl(n + 1));
    rep(r, m){
        rep(c, n) M[r][c] = A[r][c];
        M[r][n] = b[r];
    }

    ll rank = GaussJordan(M, true);
    For(r, rank, m) if (M[r][n]) return -1;

    res.assign(n, 0);
    rep(i, rank) res[i] = M[i][n];
    return rank;
}

