class UnionFind():
    def __init__(self, n):
        self.n = n
        self.par = [i for i in range(n)]
        self.size = [1 for _ in range(n)]

    def find(self, x):
        root = x
        while self.par[root] != root:
            root = self.par[root]
        while self.par[x] != root:
            par = self.par[x]
            self.par[x] = root
            x = par
        return root

    def unite(self, x, y):
        xr = self.find(x)
        yr = self.find(y)
        if xr == yr: return
        if self.size[xr] <= self.size[yr]:
            self.par[xr] = yr
            self.size[yr] += self.size[xr]
        else:
            self.par[yr] = xr
            self.size[xr] += self.size[yr]

