class UnionFind:
    """素集合を木構造として管理する。"""
    def __init__(self, n):
        self.parent = [-1] * n
        self.next = [i for i in range(n)]
        self.n = n
        self.cnt = n

    def root(self, x):
        """要素xの代表元を求める。O(α(N))"""
        if self.parent[x] < 0:
            return x
        else:
            self.parent[x] = self.root(self.parent[x])
            return self.parent[x]

    def merge(self, x, y):
        """要素xを含む集合と要素yを含む集合を併合する。O(α(N))"""
        rx = self.root(x)
        ry = self.root(y)
        if rx == ry:
            return False
        self.next[x], self.next[y] = self.next[y], self.next[x]
        if self.parent[rx] > self.parent[ry]:
            rx, ry = ry, rx
        self.parent[rx] += self.parent[ry]
        self.parent[ry] = rx
        self.next[rx]
        self.cnt -= 1
        return True

    def is_same(self, x, y):
        """要素x, yが同じ集合に属するかどうかを求める。O(α(N))"""
        return self.root(x) == self.root(y)

    def size(self, x):
        """要素xを含む集合の要素数を求める。O(α(N))"""
        return -self.parent[self.root(x)]

    def count(self):
        """集合の個数を求める。O(1)"""
        return self.cnt

    def enumerate(self):
        """集合を列挙する。list[list]で返す。O(N)"""
        groups = []
        used = [False] * n
        for x in range(n):
            if used[x]:
                continue
            grp = []
            while not used[x]:
                used[x] = True
                grp.append(x)
                x = self.next[x]
            groups.append(grp)
        return groups


